var data = msg.payload;
data.received = new Date().toISOString();

var history = flow.get('history') || [];
var nextId = (history.length > 0 ? history[history.length - 1].id : 0) + 1;
data.id = nextId;
history.push(data);
if (history.length > 50) history.shift();
flow.set('history', history);
flow.set('lastSensor', data);

var batas = flow.get('threshold') || 30.0;
var alertMsg = null;
if (data.suhu > batas) {
    alertMsg = `PERINGATAN! Suhu (${data.suhu}°C) melewati batas (${batas}°C)!`;
}

msg.payload = JSON.stringify({
    type: 'sensor_update',
    data: data,
    threshold: batas,
    alert: alertMsg
});
return msg;

msg.headers = {'Access-Control-Allow-Origin': '*'};
var data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
msg.statusCode = 200;
msg.payload = { status: 'success', data: data, server_time: new Date().toISOString() };
return msg;

msg.headers = {'Access-Control-Allow-Origin': '*'};
var key = msg.req.headers['x-api-key'];
if (key !== 'uniska-iot-2026') {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return msg;
}
var history = flow.get('history') || [];
msg.statusCode = 200;
msg.payload = { status: 'success', count: history.length, data: history.slice(-15) };
return msg;

msg.headers = {'Access-Control-Allow-Origin': '*'};
var key = msg.req.headers['x-api-key'];
if (key !== 'uniska-iot-2026') {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key salah' };
    return msg;
}
var batasBaru = parseFloat(msg.payload.threshold);
if (isNaN(batasBaru)) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Nilai threshold harus berupa angka' };
    return msg;
}
flow.set('threshold', batasBaru);
msg.statusCode = 200;
msg.payload = { status: 'success', message: `Batas suhu diatur ke ${batasBaru}°C`, threshold: batasBaru };
return msg;

msg.headers = {'Access-Control-Allow-Origin': '*'};
var key = msg.req.headers['x-api-key'];
if (key !== 'uniska-iot-2026') {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key salah' };
    return [msg, null];
}
var body = msg.payload;
var mqttMsg = { payload: body, topic: 'iot/kontrol' };
node.send([null, mqttMsg]);
msg.statusCode = 200;
msg.payload = { status: 'success', message: 'Perintah terkirim', sent: body };
return [msg, null];

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
